import { unstable_noStore } from 'next/cache'

/**
 * Renders the current time on the server for each request. Calling
 * `unstable_noStore()` opts this subtree out of static prerendering so the
 * value is never frozen at build time.
 */
export default function ServerTimestamp() {
  unstable_noStore()
  const now = new Date()
  const iso = now.toISOString()

  return (
    <p>
      Server time:{' '}
      <time dateTime={iso}>
        {now.toLocaleString(undefined, {
          dateStyle: 'medium',
          timeStyle: 'medium',
        })}
      </time>
    </p>
  )
}

